def ensure_logo():
    if os.path.exists(LOGO_PATH):
        return
    try:
        if 'LOGO_B64' in globals() and LOGO_B64:
            data = base64.b64decode(LOGO_B64)
            with open(LOGO_PATH, "wb") as f:
                f.write(data)
            print("Da tao logo BCR tu dong tu base64!")
        else:
            # tao logo tam de bot khong loi
            from PIL import Image, ImageDraw
            img = Image.new("RGBA", (200,200), (255,255,255,0))
            d = ImageDraw.Draw(img)
            d.ellipse([10,10,190,190], fill=(255,255,255,200), outline=(0,0,0,150), width=3)
            d.text((60,85), "BCR", fill=(0,0,0,200))
            img.save(LOGO_PATH, "PNG")
    except Exception as e:
        print(f"Loi tao logo: {e}")

