async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    args = context.args
    my_ref_link = f"https://t.me/{context.bot.username}?start={user_id}"
    if args and args[0].startswith("thongke"):
        total = sum(invite_data.values())
        await update.message.reply_text(f"📊 THỐNG KÊ: {total} người mới\nLink của bạn: {my_ref_link}", reply_markup=get_main_keyboard(context.bot.username))
        return
    if args and args[0].isdigit():
        ref_id = int(args[0])
        if ref_id != user_id:
            invite_data[ref_id] = invite_data.get(ref_id, 0) + 1
    if update.effective_chat.type == "private":
        await update.message.reply_text(f"Chào bạn! Link mời riêng của bạn:\n{my_ref_link}\nĐiểm: {invite_data.get(user_id, 0)}", reply_markup=get_main_keyboard(context.bot.username))

